import java.io.*;
import java.util.StringTokenizer;
class FastReader {
    BufferedReader br;
    StringTokenizer st;
    FastReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }
    long nextLong() throws IOException { return Long.parseLong(next()); }
}
public class Main {
    static long[] ones = {0, 1, 11, 111, 1111, 11111, 111111, 1111111, 11111111, 111111111, 1111111111, 11111111111L, 111111111111L, 1111111111111L, 11111111111111L, 111111111111111L, 1111111111111111L};
    public static void main(String[] args) throws IOException {
        FastReader fr = new FastReader();
        long n = fr.nextLong();
        long res = decompose(n);
        System.out.println(res);
    }
    public static long decompose(long n) {
        if (n <= 6) return n;
        long digits = getDigitCount(n);
        long lower = ones[(int) digits];
        long upper;
        if (n < lower) {
            upper = lower;
            lower = ones[(int) (digits - 1)];
        } else if (n > lower) {
            upper = ones[(int) (digits + 1)];
        } else {
            return digits;
        }
        long resLower = decompose(n % lower) + (n / lower) * getDigitCount(lower);
        long resUpper = Long.MAX_VALUE;
        if (upper - n < n) {
            resUpper = decompose(upper - n) + getDigitCount(upper);
        }
        return Math.min(resLower, resUpper);
    }
    static long getDigitCount(long n) {
        return Long.toString(n).length();
    }
}
